#include <stdio.h>
#include <stdlib.h>

typedef __int128_t int128;

typedef struct {
    int128 u;
    int128 v;
    int rank_v;
} Point;

int cmp_u(const void *a, const void *b) {
    const Point *pa = (const Point *)a;
    const Point *pb = (const Point *)b;
    if (pa->u < pb->u) return -1;
    if (pa->u > pb->u) return 1;
    return 0;
}

int cmp_v(const void *a, const void *b) {
    const Point *pa = (const Point *)a;
    const Point *pb = (const Point *)b;
    if (pa->v < pb->v) return -1;
    if (pa->v > pb->v) return 1;
    return 0;
}

int bit[100005];
int bit_size;

void bit_add(int idx, int val) {
    for (; idx <= bit_size; idx += idx & -idx) {
        bit[idx] += val;
    }
}

int bit_query(int idx) {
    int sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit[idx];
    }
    return sum;
}

int main() {
    int n;
    long long x1, x2;
    if (scanf("%d %lld %lld", &n, &x1, &x2) != 3) return 0;

    Point *pts = (Point *)malloc(n * sizeof(Point));
    Point *temp_v = (Point *)malloc(n * sizeof(Point));

    for (int i = 0; i < n; i++) {
        long long a, b;
        scanf("%lld %lld", &a, &b);
        pts[i].u = (int128)a * x1 + b;
        pts[i].v = (int128)a * x2 + b;
        temp_v[i] = pts[i];
    }

    // Compressão de coordenadas para v
    qsort(temp_v, n, sizeof(Point), cmp_v);

    int unique_v = 0;
    for (int i = 0; i < n; i++) {
        if (i == 0 || temp_v[i].v != temp_v[i - 1].v) {
            unique_v++;
        }
        temp_v[i].rank_v = unique_v;
    }

    // Mapear rank_v de volta para pts usando busca binária
    for (int i = 0; i < n; i++) {
        int l = 0, r = n - 1;
        int128 target = pts[i].v;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            if (temp_v[mid].v == target) {
                pts[i].rank_v = temp_v[mid].rank_v;
                break;
            } else if (temp_v[mid].v < target) {
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
    }

    free(temp_v);

    // Ordenar pts por u
    qsort(pts, n, sizeof(Point), cmp_u);

    bit_size = unique_v;
    for (int i = 0; i <= bit_size; i++) bit[i] = 0;

    long long concordant_pairs = 0;

    // Processar em blocos com o mesmo u
    for (int i = 0; i < n; ) {
        int j = i;
        while (j < n && pts[j].u == pts[i].u) {
            j++;
        }

        // Para cada elemento no bloco, conta quantos v anteriores são estritamente menores
        for (int k = i; k < j; k++) {
            concordant_pairs += bit_query(pts[k].rank_v - 1);
        }

        // Insere todos os elementos do bloco na BIT
        for (int k = i; k < j; k++) {
            bit_add(pts[k].rank_v, 1);
        }

        i = j;
    }

    long long total_pairs = (long long)n * (n - 1) / 2;
    long long ans = total_pairs - concordant_pairs;

    printf("%lld\n", ans);

    free(pts);
    return 0;
}
